<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { useResearchStore } from '../stores/research'
import AddPaperDialog from '../components/AddPaperDialog.vue'
import PaperReaderPicker from '../components/PaperReaderPicker.vue'
import { downloadBlob } from '../lib/storage'
import Sidebar from '../components/AppSidebar.vue'
import Icon from '../components/AppIcon.vue'
import Canvas from '../components/ResearchCanvas.vue'
import Assistant from '../components/ResearchAssistant.vue'
import SegmentedControl from '../components/AnimatedSegmentedControl.vue'
import { useCopilotStore } from '../stores/copilot'
import AnalysisResult from '../components/AnalysisResult.vue'
import type { AnalysisTask } from '../types/copilot'
import {useBackendStore,errorText} from '../stores/backend'
import {useAssistantWidth} from '../composables/useAssistantWidth'
import {useWorkspaceHeight} from '../composables/useWorkspaceHeight'
const store=useResearchStore(),route=useRoute(),router=useRouter(),mode=ref<'cards'|'graph'|'list'>('cards'),assistantVisible=ref(true),filter=ref('all'),canvas=ref<InstanceType<typeof Canvas>>()
const views=[{value:'cards',label:'空间画布',icon:'LayoutGrid'},{value:'graph',label:'论文图谱',icon:'Network'},{value:'list',label:'列表',icon:'List'}] as const
const readerPickerOpen=ref(false)
const copilot=useCopilotStore()
const backend=useBackendStore()
const {headerRegion,contentRegion,workspaceRegion,height,maxHeight,minHeight,headerStyle,resizing,adjust,reset,begin,move,end,keys}=useWorkspaceHeight()
const {splitRegion,width:assistantWidth,style:assistantWidthStyle,limits:assistantWidthLimits,resizing:resizingAssistant,begin:beginAssistantResize,move:moveAssistantResize,end:endAssistantResize,keys:assistantResizeKeys,adjust:adjustAssistantWidth,reset:resetAssistantWidth}=useAssistantWidth()
const taskBusy=computed(()=>store.organizingPapers||store.connectingPapers||copilot.busy||backend.busy)
const paperScope=computed(()=>store.selectedIds.length?store.selectedIds:store.visibleIds)
watch(()=>route.params.id,id=>{if(id&&String(id)!==store.activeId&&!route.path.startsWith('/graphs'))store.loadSession(String(id))},{immediate:true})
watch(()=>store.activeId,id=>{if(id&&String(route.params.id||'')!==id&&!route.path.startsWith('/graphs'))void router.replace({path:'/chat/'+id,query:route.query})},{immediate:true})
watch(()=>[store.activeId,copilot.busy,backend.busy],()=>{if(!copilot.busy&&!backend.busy)void backend.switchWorkspace(store.activeId||'default').catch(e=>store.notify(errorText(e)))},{immediate:true})
watch(()=>copilot.state,value=>{if(value==='loading'||value==='error')assistantVisible.value=true})
function analyzeSelected(task:AnalysisTask){store.selectedPaperId=null;store.selectedRelation=null;copilot.sourceMode='papers';assistantVisible.value=true;void copilot.analyze(task)}
function setView(value:string){if(value==='cards'||value==='graph'||value==='list')mode.value=value}
onMounted(()=>{if(route.params.id&&!route.path.startsWith('/graphs'))store.loadSession(String(route.params.id));if(route.path.startsWith('/graphs')&&!store.disabledSkills.includes('citation_graph'))mode.value='graph';if(window.innerWidth<1050)assistantVisible.value=Boolean(store.selectedPaperId||route.query.compose==='1')})
onMounted(()=>{if(route.query.intent==='question')copilot.questionMode=true;if(route.query.intent==='materials')copilot.sourceMode='materials';if(route.query.intent==='compare')copilot.tableOpen=true})
async function deck(){const result=await store.createDeck();if(result)router.push('/artifacts/'+result.id)}
function exportGraph(){downloadBlob(JSON.stringify({kind:'user-research-space',notice:'主题关联，非真实引用关系',query:store.question,nodes:store.activePapers,edges:store.edges.filter(([a,b])=>store.visibleIds.includes(a!)&&store.visibleIds.includes(b!)),relations:store.relationDetails},null,2),'Orbit-研究图谱.json','application/json');store.notify('图谱已导出为 JSON。')}
function open(id:string){store.selectedRelation=null;store.selectedPaperId=id;assistantVisible.value=true}
function relation(ids:[string,string]){store.selectedPaperId=null;store.selectedRelation=ids;assistantVisible.value=true;copilot.tab='analysis'}
</script>
<template>
  <div class="app-shell"><Sidebar/><PaperReaderPicker v-if="readerPickerOpen" @close="readerPickerOpen=false"/><AddPaperDialog v-if="store.paperEditorOpen" :paper="store.paperById(store.paperEditorId)" @close="store.paperEditorOpen=false;store.paperEditorId=''"/><main id="main-content" class="workspace-main">
    <header class="workspace-header"><button class="icon-button mobile-menu-button" aria-label="打开导航" @click="store.mobileMenu=true"><Icon name="Menu"/></button><div class="workspace-header-actions"><button class="secondary-button" @click="readerPickerOpen=true"><Icon name="BookOpen" :size="15"/><span>论文阅读</span></button><button class="secondary-button" aria-label="导出研究图谱" @click="exportGraph"><Icon name="Download" :size="15"/><span>导出</span></button><button class="primary-button micro-shimmer" :disabled="store.generatingDeck" @click="deck"><Icon name="Presentation" :size="15"/><span>{{store.generatingDeck?'正在生成…':'生成汇报'}}</span></button></div></header>
    <div ref="splitRegion" class="workspace-split" :class="{'assistant-hidden':!assistantVisible,'resizing-assistant':resizingAssistant}" :style="assistantWidthStyle"><section ref="workspaceRegion" class="spatial-workspace" :class="{'is-resizing-header':resizing}" aria-label="研究空间">
      <div id="workspace-intro" ref="headerRegion" class="workspace-intro" :class="{'is-compact':(height||170)<115}" :style="headerStyle"><div class="workspace-title"><div><div class="workspace-eyebrow"><span class="status-dot"></span>RESEARCH SPACE</div><h1>{{store.sessions.find(s=>s.id===store.activeId)?.customTitle||store.question||'从你的研究问题开始'}}</h1><p>让分散的论文，成为相连的理解。</p></div><button class="icon-button" :aria-label="assistantVisible?'隐藏研究助手':'显示研究助手'" @click="assistantVisible=!assistantVisible"><Icon :name="assistantVisible?'PanelRightClose':'PanelRightOpen'"/></button></div></div>
      <div class="canvas-tabs-toolbar"><div class="paper-management-actions"><button class="secondary-button" @click="store.paperEditorOpen=true"><Icon name="Plus" :size="15"/>添加论文</button><button class="secondary-button paper-organize-button" :disabled="!store.activePapers.length||taskBusy" @click="store.organizePapers(paperScope)"><Icon :name="store.organizingPapers?'LoaderCircle':'Sparkles'" :class="{spin:store.organizingPapers}" :size="15"/>AI 整理 {{paperScope.length}} 篇</button><button v-if="store.activePapers.length>=2" class="text-button" :disabled="taskBusy" @click="store.connectSelected()">分析联系</button></div><SegmentedControl :model-value="mode" :options="views" label="研究视图" id-prefix="research-view" panel-id="research-view-panel" @update:model-value="setView"/><button class="icon-button" aria-label="上传研究材料" @click="store.uploadOpen=true"><Icon name="Upload" :size="17"/></button></div>
      <div class="canvas-context-bar"><div class="graph-legend"><span class="foundation">用户论文</span><span class="retrieval">选中资料</span><span class="reliability">AI 主题联系</span></div><div class="workspace-resize-controls"><button class="icon-button" aria-label="收起标题区，增大画布" @click="adjust(-40)"><Icon name="ChevronUp" :size="14"/></button><div role="separator" tabindex="0" aria-label="上下拖动调整标题区与画布高度" aria-orientation="horizontal" aria-controls="workspace-intro" :aria-valuemin="minHeight" :aria-valuemax="maxHeight" :aria-valuenow="height||minHeight" :aria-valuetext="`标题区高度 ${height||minHeight} 像素`" class="workspace-height-handle" title="上下拖动 · 方向键调整 · 双击还原" @pointerdown="begin" @pointermove="move" @pointerup="end" @pointercancel="end" @lostpointercapture="end" @keydown="keys" @dblclick="reset"><span></span></div><button class="icon-button" aria-label="展开标题区" @click="adjust(40)"><Icon name="ChevronDown" :size="14"/></button></div><span>{{store.visibleIds.length}} 篇文献<span class="context-dot">·</span>{{store.edges.length}} 条主题联系</span></div>
      <section v-if="store.processingLabel||store.processingError" class="paper-processing-notice" aria-label="论文整理状态"><div><Icon :name="taskBusy?'LoaderCircle':'Sparkles'" :class="{spin:taskBusy}" :size="14"/><span role="status">{{store.processingLabel||'AI 整理论文'}}</span><button v-if="store.organizingPapers||store.connectingPapers" class="text-button" @click="store.stopPaperProcessing()">停止</button><RouterLink v-else-if="!backend.modelMode" to="/settings#model">连接模型 API</RouterLink></div><details v-if="store.processingError"><summary>查看需处理的问题</summary><p>{{store.processingError}}</p></details></section>
      <p v-else-if="store.activePapers.length&&!store.edges.length" class="paper-processing-hint">点击「AI 整理」提取题名、作者、年份，并分析当前资料的主题联系。<RouterLink v-if="!backend.modelMode" to="/settings#model">先连接模型 API ↗</RouterLink></p>
      <section v-if="store.incompletePapers.length&&!taskBusy" class="paper-processing-notice" aria-label="待补全论文"><details open><summary>{{store.incompletePapers.length}} 篇论文需要补充或重试</summary><div v-for="paper in store.incompletePapers" :key="paper.id" class="paper-retry-row"><span><strong>{{paper.title}}</strong><small>{{paper.metadataError||'尚未整理题录'}}</small></span><button class="text-button" @click="store.organizePapers([paper.id],false)">单篇重试</button><button class="text-button" @click="store.editPaper(paper.id)">手动补充</button></div></details></section>
      <Transition name="copilot-context"><div v-if="store.selectedIds.length>=2" class="selection-action-bar" aria-label="已选论文操作"><span role="status" aria-atomic="true">已选 {{store.selectedIds.length}} 篇</span><button :disabled="copilot.busy" @click="analyzeSelected('compare')">AI 对比分析</button><button :disabled="copilot.busy" @click="analyzeSelected('common')">总结共同点</button><details><summary>更多操作</summary><button :disabled="copilot.busy" @click="analyzeSelected('methods')">分析方法差异</button><button :disabled="copilot.saving" @click="store.selectedPaperId=null;store.selectedRelation=null;copilot.saveSelection();assistantVisible=true">加入研究笔记</button><button :disabled="store.connectingPapers" @click="store.connectSelected()">{{store.connectingPapers?'正在分析联系…':'AI 关联分析'}}</button><button :disabled="store.generatingDeck" @click="deck">生成汇报</button></details></div></Transition>
      <div ref="contentRegion" class="research-workspace-content"><div v-show="!copilot.tableOpen" class="canvas-stage">
      <div v-if="!store.activePapers.length" class="workspace-paper-empty empty-state"><Icon name="BookOpen" :size="36"/><h2>从你自己的论文开始</h2><p>上传 PDF，或手动添加论文标题、作者与原文链接。空间中不会自动填入论文。</p><div class="button-row"><button class="primary-button" @click="store.uploadOpen=true">上传论文 PDF</button><button class="secondary-button" @click="store.paperEditorOpen=true">手动添加论文</button></div></div><Canvas v-else-if="mode!=='list'" id="research-view-panel" ref="canvas" :mode="mode" role="tabpanel" :aria-labelledby="`research-view-${mode}`" @open="open" @relation="relation"/>
      <div v-else id="research-view-panel" class="paper-list-view" role="tabpanel" :aria-labelledby="`research-view-${mode}`"><div class="list-filter"><label for="year-filter">发表时间</label><select id="year-filter" v-model="filter"><option value="all">全部年份</option><option value="recent">2023 年及以后</option><option value="foundation">2020 年及以前</option></select></div><button v-for="paper in store.activePapers.filter(p=>filter==='all'||(filter==='recent'?p.year>=2023:p.year<=2020))" :key="paper.id" class="paper-list-row" @click="open(paper.id)"><span class="paper-list-icon" :class="paper.category"><Icon name="FileText" :size="21"/></span><div><strong>{{paper.title}}</strong><span>{{paper.authors}} · {{paper.year||'年份待补充'}} · {{paper.localDocumentId?'PDF 文件':paper.url?'用户提供原文':'用户提供元数据'}}</span><p>{{paper.summary}}</p></div><Icon name="ArrowUpRight"/></button><div v-if="!store.activePapers.length" class="empty-state"><Icon name="Compass" :size="38"/><h2>线索正在浮现</h2><p>稍后即可在这里查看论文。</p></div></div>
      </div><section v-if="copilot.tableOpen" class="analysis-board" aria-label="论文对比结果"><div class="model-conversation-heading"><h2>论文对比分析</h2><div class="button-row"><button v-if="copilot.current?.result" class="secondary-button" :disabled="copilot.saving" @click="copilot.saveAnalysis()">保存到空间笔记</button><button class="text-button" @click="copilot.tableOpen=false">返回研究画布</button></div></div><p v-if="copilot.contextChanged" class="analysis-scope">选择已改变，当前显示的是上一次分析的来源快照。</p><p v-if="copilot.busy" role="status">正在分析所选材料，画布位置会保留…</p><p v-if="copilot.error" class="form-error" role="alert">{{copilot.error}}</p><AnalysisResult v-if="copilot.current?.result" :analysis="copilot.current" expanded/><p v-else-if="!copilot.busy&&!copilot.error" class="settings-hint">选择 2–5 篇论文，开始一次有明确来源的比较。</p></section></div>
      <div class="workspace-bottom-bar"><span><Icon name="CheckCheck" :size="14"/>{{store.isSearching?'正在组织论文…':`${store.selectedIds.length} 篇已选为汇报材料`}}</span><button v-if="store.isSearching" class="text-button" @click="store.cancel()"><Icon name="Square" :size="12"/>停止展开</button><button v-else class="text-button" @click="store.expand()"><Icon name="Plus" :size="14"/>添加研究论文</button></div>
    </section><div v-if="assistantVisible" class="assistant-divider"><div role="separator" tabindex="0" class="assistant-width-handle" aria-label="左右拖动调整研究助手宽度" aria-orientation="vertical" aria-controls="orbit-research-assistant" :aria-valuemin="assistantWidthLimits.min" :aria-valuemax="assistantWidthLimits.max" :aria-valuenow="assistantWidth||344" :aria-valuetext="`研究助手宽度 ${assistantWidth||344} 像素`" title="左右拖动调整宽度 · 双击还原 · 左右方向键微调" @pointerdown="beginAssistantResize" @pointermove="moveAssistantResize" @pointerup="endAssistantResize" @pointercancel="endAssistantResize" @lostpointercapture="endAssistantResize" @keydown="assistantResizeKeys" @dblclick="resetAssistantWidth"><span></span></div><div class="assistant-width-buttons"><button aria-label="加宽研究助手" @click="adjustAssistantWidth(40)"><Icon name="ChevronLeft" :size="13"/></button><button aria-label="缩小研究助手" @click="adjustAssistantWidth(-40)"><Icon name="ChevronRight" :size="13"/></button></div></div><Assistant v-if="assistantVisible" @close="assistantVisible=false"/></div>
    <button v-if="!assistantVisible" class="assistant-reopen primary-button" @click="assistantVisible=true"><Icon name="Sparkles"/>研究助手</button>
  </main></div>
</template>
